function check(candidate) {
    console.assert(JSON.stringify(candidate([2,5,1,2,5], [10,5,2,1,5,2])) === JSON.stringify(3));
    console.assert(JSON.stringify(candidate([1,4,2], [1,2,4])) === JSON.stringify(2));
    console.assert(JSON.stringify(candidate([3,3,3,3,3,3,3], [3,3,3,3,3,3,3])) === JSON.stringify(7));
    console.assert(JSON.stringify(candidate([1,2,2,1], [2,1,1,2])) === JSON.stringify(2));
    console.assert(JSON.stringify(candidate([5], [5])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,1,1,1], [1,1,1,1])) === JSON.stringify(4));
    console.assert(JSON.stringify(candidate([1,2,3], [3,2,1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,2,3,4,5], [5,4,3,2,1])) === JSON.stringify(1));
    console.assert(JSON.stringify(candidate([1,2,3,3,4,5], [3,3,3])) === JSON.stringify(2));
    console.assert(JSON.stringify(candidate([1,2,3,3,2,1], [1,2,3,4,3,2,1])) === JSON.stringify(6));
    console.assert(JSON.stringify(candidate([5,1,4,2], [5,2,1,4])) === JSON.stringify(3));
    console.assert(JSON.stringify(candidate([1,3,7,1,7,5], [1,9,2,5,1])) === JSON.stringify(2));
